// Prints accuracy/REPORT.md: how Lux Studio's direct illuminance compares with
// Radiance's in each reference room. `npm run accuracy:report` bundles this
// with Vite, runs it in Node and writes its output to the file.
import { BRIGHT_SHARE, compareReference, NEAR_M, summarize } from './compare';
import { IES_FILES, REFERENCES } from './inputs';

const percent = (value: number) => `${(value * 100).toFixed(2)} %`;
const lux = (value: number) => value.toFixed(1);

const lines: string[] = [
  '# Accuracy: Lux Studio against Radiance',
  '',
  'Generated by `npm run accuracy:report` from `accuracy/references` (ADR 0058). Direct',
  'light only, as installed (no maintenance factor). "Bright" points have at least',
  `${BRIGHT_SHARE * 100} % of the room's brightest point; "near" ones are within ${NEAR_M} m of a luminaire.`,
  '',
];
for (const [name, reference] of Object.entries(REFERENCES)) {
  const points = compareReference(reference, IES_FILES);
  const origins = reference.room.luminaires.map((luminaire) => luminaire.origin);
  lines.push(
    `## ${name}`,
    '',
    reference.room.description,
    '',
    `Radiance ${reference.radiance.release}, ${points.length} points.`,
    '',
    '| Surface | Points | Radiance Ē (lx) | Lux Studio Ē (lx) | Ē difference | Worst bright point, far | Worst bright point, near |',
    '|---|---|---|---|---|---|---|',
  );
  for (const summary of summarize(points, origins)) {
    lines.push(
      `| ${summary.surface} | ${summary.points} | ${lux(summary.radianceAverageLx)} | ` +
        `${lux(summary.oursAverageLx)} | ${percent(summary.averageError)} | ` +
        `${summary.worstFar > 0 ? percent(summary.worstFar) : '–'} | ` +
        `${summary.worstNear > 0 ? percent(summary.worstNear) : '–'} |`,
    );
  }
  lines.push('');
}
console.log(lines.join('\n'));
